        if (rented_subtype %in% c(1, 2, 3)) return(4)  # Rent it
        if (rented_subtype == 4) return(5)  # Rent free
        if (rented_subtype == 5) return(6)  # Other
      }
    }
  } else if (wave_group %in% c('8-9')) {
    if (value == 6) return(6)  # Squatting
    if (value == 7) return(6)  # Other
  }

  return(value)
}

