    owned_var <- paste0('W', substr(wave, 6, 6), 'Hous12bYP')
    rented_var <- paste0('W', substr(wave, 6, 6), 'Hous12cYP')

    df[[var_name]] <- type_var
    df[[var_name]][type_var == 1] <- owned_var[type_var == 1]
    df[[var_name]][type_var == 2] <- rented_var[type_var == 2]
    df[[var_name]] <- map_detailed(df[[var_name]], '5-7')
  }

  # Apply missing value mapping
  df[[var_name]] <- map_missing(df[[var_name]], '1-7')
  return(df)
}

# Create collapsed variables (6 categories)
create_collapsed_variables <- function(df, wave) {
  age <- wave_to_age(wave)
  var_name <- paste0('hown', age)

  if (wave %in% c('wave1', 'wave2', 'wave3', 'wave4')) {
    src_var <- paste0('W', substr(wave, 6, 6), 'hous12HH')
    df[[var_name]] <- map_collapsed(df[[src_var]], '1-4')
  } else if (wave %in% c('wave5', 'wave6', 'wave7')) {
    type_var <- paste0('W', substr(wave, 6, 6), 'Hous12YP')
    owned_var <- paste0('W', substr(wave, 6, 6), 'Hous12bYP')
    rented_var <- paste0('W', substr(wave, 6, 6), 'Hous12cYP')

    df[[var_name]] <- type_var
    df[[var_name]][type_var == 1] <- owned_var[type_var == 1]
    df[[var_name]][type_var == 2] <- rented_var[type_var == 2]
    df[[var_name]] <- map_collapsed(df[[var_name]], '5-7')
  } else if (wave %in% c('wave8', 'wave9')) {
    src_var <- paste0('W', substr(wave, 6, 6), 'TENURE')
    df[[var_name]] <- map_collapsed(df[[src_var]], '8-9')
  }

  # Apply missing value mapping
  df[[var_name]] <- map_missing(df[[var_name]], ifelse(wave %in% c('wave8', 'wave9'), '8-9', '1-7'))
  return(df)
}

# Apply detailed and collapsed variable creation for each wave
detailed_waves <- c('wave1', 'wave2', 'wave3', 'wave4', 'wave5', 'wave6', 'wave7')
collapsed_waves <- c('wave1', 'wave2', 'wave3', 'wave4', 'wave5', 'wave6', 'wave7', 'wave8', 'wave9')

for (wave in detailed_waves) {
  merged_data <- create_detailed_variables(merged_data, wave)
}

for (wave in collapsed_waves) {
  merged_data <- create_collapsed_variables(merged_data, wave)
}

# Define value labels for detailed (8 categories) and collapsed (6 categories) variables
detailed_labels <- c(
  '-9' = 'Refused',
  '-8' = 'Don\'t know',
  '-3' = 'Not asked',
  '1' = 'Owned outright',
  '2' = 'Being bought on a mortgage/loan',
  '3' = 'Shared ownership',
  '4' = 'Rented from Council',
  '5' = 'Rented from Housing Association',
  '6' = 'Rented privately',
  '7' = 'Rent free',
  '8' = 'Some other arrangement'
)

collapsed_labels <- c(
  '-9' = 'Refused',
  '-8' = 'Don\'t know',
  '-3' = 'Not asked',
  '-1' = 'Not applicable',
  '1' = 'Own outright',
  '2' = 'Own, buying with help of mortgage/loan',
  '3' = 'Part rent, part mortgage (shared equity)',
  '4' = 'Rent it',
  '5' = 'Live rent-free',
  '6' = 'Other'
)

# Apply labels to detailed variables
detailed_vars <- grep('^hownteen', names(merged_data), value = TRUE)
for (var in detailed_vars) {
  merged_data[[var]] <- labelled(merged_data[[var]], detailed_labels)
}

# Apply labels to collapsed variables
collapsed_vars <- grep('^hown', names(merged_data), value = TRUE)
for (var in collapsed_vars) {
  merged_data[[var]] <- labelled(merged_data[[var]], collapsed_labels)
}

# Select only NSID and derived housing tenure variables
final_vars <- c('NSID', grep('^hown', names(merged_data), value = TRUE))

final_data <- merged_data %>% select(all_of(final_vars))

# Write output to CSV
write_csv(final_data, 'data/output/cleaned_data.csv')
