# Load required libraries
library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Load metadata and define file paths
metadata <- list(
  wave1 = 'data/input/wave_one_lsype_family_background_2020.tab',
  wave2 = 'data/input/wave_two_lsype_family_background_2020.tab',
  wave3 = 'data/input/wave_three_lsype_family_background_2020.tab',
  wave4 = 'data/input/wave_four_lsype_family_background_2020.tab',
  wave5 = 'data/input/wave_five_lsype_family_background_2020.tab',
  wave6 = 'data/input/wave_six_lsype_young_person_2020.tab',
  wave7 = 'data/input/wave_seven_lsype_young_person_2020.tab',
  wave8 = 'data/input/ns8_2015_main_interview.tab',
  wave9 = 'data/input/ns9_2022_derived_variables.tab'
)

# Load all files into separate data frames
load_files <- function(file_path) {
  read_delim(file_path, delim = '\\t')
}

loaded_dfs <- map(metadata, load_files)

# Assign each loaded file to a variable
wave1 <- loaded_dfs[[1]]
wave2 <- loaded_dfs[[2]]
wave3 <- loaded_dfs[[3]]
wave4 <- loaded_dfs[[4]]
wave5 <- loaded_dfs[[5]]
wave6 <- loaded_dfs[[6]]
wave7 <- loaded_dfs[[7]]
wave8 <- loaded_dfs[[8]]
wave9 <- loaded_dfs[[9]]

# Merge all datasets using full_join on NSID
