  full_join(wave3, by = 'NSID') %>%
  full_join(wave4, by = 'NSID') %>%
  full_join(wave5, by = 'NSID') %>%
  full_join(wave6, by = 'NSID') %>%
  full_join(wave7, by = 'NSID') %>%
  full_join(wave8, by = 'NSID') %>%
  full_join(wave9, by = 'NSID')

# Define mapping functions for missing values
map_missing <- function(value, wave_group) {
  if (is.na(value)) {
    return(-3)  # Default for NA
  }

  if (wave_group %in% c('1-4')) {
    if (value == -1) return(-8)  # Don't know maps to -8
    if (value == -92) return(-9)  # Refused maps to -9
  } else if (wave_group %in% c('8-9')) {
    if (value == -1) return(-1)  # Retain standard meaning
  }

  return(value)
}

# Define mapping for detailed categories (8 categories)
map_detailed <- function(value, wave_group) {
  if (value == -1) return(-8)
  if (value == -92) return(-9)

  if (wave_group %in% c('1-4')) {
    return(value)
  } else if (wave_group %in% c('5-7')) {
    if (value == 1) return(1)  # Owned
    if (value == 2) return(2)  # Rented
    if (value == 3) return(8)  # Some other arrangement
  }
  return(value)
}

# Define mapping for collapsed categories (6 categories)
map_collapsed <- function(value, wave_group) {
