        if (owned_subtype == 4) return(6)  # Other
      }
    } else if (value == 2) {
      # Check rented-subtype
      rented_subtype <- merged_data[[paste0('W', wave_group, 'Hous12CHH')]]
      if (!is.na(rented_subtype)) {
