    df[[var_name]][type_var == 1] <- owned_var[type_var == 1]
    df[[var_name]][type_var == 2] <- rented_var[type_var == 2]
    df[[var_name]] <- map_detailed(df[[var_name]], '5-7')
  }

  # Apply missing value mapping
  df[[var_name]] <- map_missing(df[[var_name]], '1-7')
  return(df)
}

# Create collapsed variables (6 categories)
create_collapsed_variables <- function(df, wave) {
