  wave7 = 'data/input/wave_seven_lsype_young_person_2020.tab',
  wave8 = 'data/input/ns8_2015_main_interview.tab',
  wave9 = 'data/input/ns9_2022_derived_variables.tab'
)

# Load all files into separate data frames
load_files <- function(file_path) {
  read_delim(file_path, delim = '\\t')
}

loaded_dfs <- map(metadata, load_files)

# Assign each loaded file to a variable
wave1 <- loaded_dfs[[1]]
wave2 <- loaded_dfs[[2]]
wave3 <- loaded_dfs[[3]]
wave4 <- loaded_dfs[[4]]
wave5 <- loaded_dfs[[5]]
wave6 <- loaded_dfs[[6]]
wave7 <- loaded_dfs[[7]]
wave8 <- loaded_dfs[[8]]
wave9 <- loaded_dfs[[9]]

# Merge all datasets using full_join on NSID
merged_data <- full_join(wave1, wave2, by = 'NSID') %>%
  full_join(wave3, by = 'NSID') %>%
  full_join(wave4, by = 'NSID') %>%
  full_join(wave5, by = 'NSID') %>%
  full_join(wave6, by = 'NSID') %>%
  full_join(wave7, by = 'NSID') %>%
  full_join(wave8, by = 'NSID') %>%
  full_join(wave9, by = 'NSID')

# Define mapping functions for missing values
map_missing <- function(value, wave_group) {
  if (is.na(value)) {
    return(-3)  # Default for NA
  }

  if (wave_group %in% c('1-4')) {
    if (value == -1) return(-8)  # Don't know maps to -8
    if (value == -92) return(-9)  # Refused maps to -9
  } else if (wave_group %in% c('8-9')) {
    if (value == -1) return(-1)  # Retain standard meaning
  }

  return(value)
}

# Define mapping for detailed categories (8 categories)
map_detailed <- function(value, wave_group) {
  if (value == -1) return(-8)
  if (value == -92) return(-9)

  if (wave_group %in% c('1-4')) {
    return(value)
  } else if (wave_group %in% c('5-7')) {
    if (value == 1) return(1)  # Owned
    if (value == 2) return(2)  # Rented
    if (value == 3) return(8)  # Some other arrangement
  }
  return(value)
}

# Define mapping for collapsed categories (6 categories)
map_collapsed <- function(value, wave_group) {
  if (value == -1) {
    if (wave_group %in% c('1-4')) return(-8)
    else return(-1)
  }
  if (value == -92) return(-9)

  if (wave_group %in% c('1-4')) {
    if (value == 4 || value == 5 || value == 6) return(4)  # Rent it
    if (value == 8) return(6)  # Other
  } else if (wave_group %in% c('5-7')) {
    if (value == 1) {
      # Check owned-subtype
      owned_subtype <- merged_data[[paste0('W', wave_group, 'Hous12BHH')]]
      if (!is.na(owned_subtype)) {
        if (owned_subtype == 1) return(1)  # Own outright
        if (owned_subtype == 2) return(2)  # Own with mortgage
        if (owned_subtype == 3) return(3)  # Shared ownership
        if (owned_subtype == 4) return(6)  # Other
      }
    } else if (value == 2) {
      # Check rented-subtype
      rented_subtype <- merged_data[[paste0('W', wave_group, 'Hous12CHH')]]
      if (!is.na(rented_subtype)) {
        if (rented_subtype %in% c(1, 2, 3)) return(4)  # Rent it
        if (rented_subtype == 4) return(5)  # Rent free
        if (rented_subtype == 5) return(6)  # Other
      }
    }
  } else if (wave_group %in% c('8-9')) {
    if (value == 6) return(6)  # Squatting
    if (value == 7) return(6)  # Other
  }

  return(value)
}

# Define age mapping for waves
wave_to_age <- function(wave) {
  switch(wave,
         'wave1' = 14,
         'wave2' = 15,
         'wave3' = 16,
         'wave4' = 17,
         'wave5' = 18,
         'wave6' = 19,
         'wave7' = 20,
         'wave8' = 25,
         'wave9' = 32)
}

# Create detailed variables (8 categories)
create_detailed_variables <- function(df, wave) {
  age <- wave_to_age(wave)
  var_name <- paste0('hownteen', age)

  if (wave %in% c('wave1', 'wave2', 'wave3', 'wave4')) {
    src_var <- paste0('W', substr(wave, 6, 6), 'hous12HH')
    df[[var_name]] <- map_detailed(df[[src_var]], '1-4')
  } else if (wave %in% c('wave5', 'wave6', 'wave7')) {
    type_var <- paste0('W', substr(wave, 6, 6), 'Hous12YP')
    owned_var <- paste0('W', substr(wave, 6, 6), 'Hous12bYP')
    rented_var <- paste0('W', substr(wave, 6, 6), 'Hous12cYP')

    df[[var_name]] <- type_var
    df[[var_name]][type_var == 1] <- owned_var[type_var == 1]
    df[[var_name]][type_var == 2] <- rented_var[type_var == 2]
    df[[var_name]] <- map_detailed(df[[var_name]], '5-7')
  }

  # Apply missing value mapping
  df[[var_name]] <- map_missing(df[[var_name]], '1-7')
  return(df)
}

# Create collapsed variables (6 categories)
create_collapsed_variables <- function(df, wave) {
  age <- wave_to_age(wave)
  var_name <- paste0('hown', age)

  if (wave %in% c('wave1', 'wave2', 'wave3', 'wave4')) {
    src_var <- paste0('W', substr(wave, 6, 6), 'hous12HH')
    df[[var_name]] <- map_collapsed(df[[src_var]], '1-4')
  } else if (wave %in% c('wave5', 'wave6', 'wave7')) {
    type_var <- paste0('W', substr(wave, 6, 6), 'Hous12YP')
    owned_var <- paste0('W', substr(wave, 6, 6), 'Hous12bYP')
    rented_var <- paste0('W', substr(wave, 6, 6), 'Hous12cYP')

    df[[var_name]] <- type_var
    df[[var_name]][type_var == 1] <- owned_var[type_var == 1]
    df[[var_name]][type_var == 2] <- rented_var[type_var == 2]
    df[[var_name]] <- map_collapsed(df[[var_name]], '5-7')
  } else if (wave %in% c('wave8', 'wave9')) {
    src_var <- paste0('W', substr(wave, 6, 6), 'TENURE')
    df[[var_name]] <- map_collapsed(df[[src_var]], '8-9')
  }

  # Apply missing value mapping
  df[[var_name]] <- map_missing(df[[var_name]], ifelse(wave %in% c('wave8', 'wave9'), '8-9', '1-7'))
  return(df)
}

# Apply detailed and collapsed variable creation for each wave
detailed_waves <- c('wave1', 'wave2', 'wave3', 'wave4', 'wave5', 'wave6', 'wave7')
collapsed_waves <- c('wave1', 'wave2', 'wave3', 'wave4', 'wave5', 'wave6', 'wave7', 'wave8', 'wave9')

for (wave in detailed_waves) {
  merged_data <- create_detailed_variables(merged_data, wave)
}

for (wave in collapsed_waves) {
  merged_data <- create_collapsed_variables(merged_data, wave)
}

# Define value labels for detailed (8 categories) and collapsed (6 categories) variables
detailed_labels <- c(
  '-9' = 'Refused',
  '-8' = 'Don\'t know',
  '-3' = 'Not asked',
  '1' = 'Owned outright',
  '2' = 'Being bought on a mortgage/loan',
  '3' = 'Shared ownership',
  '4' = 'Rented from Council',
  '5' = 'Rented from Housing Association',
  '6' = 'Rented privately',
  '7' = 'Rent free',
  '8' = 'Some other arrangement'
)

collapsed_labels <- c(
  '-9' = 'Refused',
  '-8' = 'Don\'t know',
  '-3' = 'Not asked',
  '-1' = 'Not applicable',
  '1' = 'Own outright',
  '2' = 'Own, buying with help of mortgage/loan',
  '3' = 'Part rent, part mortgage (shared equity)',
  '4' = 'Rent it',
  '5' = 'Live rent-free',
  '6' = 'Other'
)

# Apply labels to detailed variables
detailed_vars <- grep('^hownteen', names(merged_data), value = TRUE)
for (var in detailed_vars) {
  merged_data[[var]] <- labelled(merged_data[[var]], detailed_labels)
}

# Apply labels to collapsed variables
collapsed_vars <- grep('^hown', names(merged_data), value = TRUE)
for (var in collapsed_vars) {
  merged_data[[var]] <- labelled(merged_data[[var]], collapsed_labels)
}

# Select only NSID and derived housing tenure variables
final_vars <- c('NSID', grep('^hown', names(merged_data), value = TRUE))

final_data <- merged_data %>% select(all_of(final_vars))

# Write output to CSV
write_csv(final_data, 'data/output/cleaned_data.csv')
"
  }
}
